BEGIN TRANSACTION;
CREATE TABLE advances (
 id TEXT PRIMARY KEY REFERENCES merges(id) DEFERRABLE INITIALLY DEFERRED,
 target TEXT NOT NULL REFERENCES heads(id) DEFERRABLE INITIALLY DEFERRED,
 expected_target TEXT NOT NULL, candidate TEXT NOT NULL,
 delivery TEXT NOT NULL REFERENCES deliveries(id) DEFERRABLE INITIALLY DEFERRED,
 status TEXT NOT NULL CHECK(status IN ('prepared','dispatched','observed','applied','needs_reconciliation','not_applied')),
 receipt TEXT, revision INTEGER NOT NULL, reason TEXT NOT NULL, provider TEXT NOT NULL
, context JSON CHECK(context IS NULL OR json_valid(context)));
INSERT INTO "advances" VALUES('1bf2e2b7-8591-4223-a479-044eb696676a','5f267ae7-93d5-4ab6-8162-54d62c32ad03','sim-rev-root','sim-rev-candidate-1bf2e2b7-8591-4223-a479-044eb696676a','ad7219de-d1e0-4c10-bdab-59b3a2f933f6','applied','sim-rev-candidate-1bf2e2b7-8591-4223-a479-044eb696676a',4,'回执、目标与验收一致，已提交工程结果','devdesk_adapters::SimGit','{"origin":"simulated","project":"1c79ee9f-12c6-405a-933e-c7d7071cfc2d","source":{"branch":"task/3667d945-1cf1-4778-8359-b831df49e252","owner":"3667d945-1cf1-4778-8359-b831df49e252","worktree":"logical-worktree/3667d945-1cf1-4778-8359-b831df49e252"},"target":{"branch":"feature/5f267ae7-93d5-4ab6-8162-54d62c32ad03","owner":"5f267ae7-93d5-4ab6-8162-54d62c32ad03","worktree":"logical-feature/5f267ae7-93d5-4ab6-8162-54d62c32ad03"},"workspace":{"mainline":"main","path":"","repository":""}}');
CREATE TABLE "artifacts" (
 "id" TEXT PRIMARY KEY,
 "feature_id" TEXT REFERENCES features(id) DEFERRABLE INITIALLY DEFERRED,
 "task_id" TEXT REFERENCES tasks(id) DEFERRABLE INITIALLY DEFERRED,
 "relative_path" TEXT NOT NULL,
 "sha256" TEXT NOT NULL,
 "media_type" TEXT NOT NULL,
 "origin" TEXT NOT NULL
,
 project_id TEXT REFERENCES projects(id) DEFERRABLE INITIALLY DEFERRED,
 CHECK ((project_id IS NOT NULL) != (feature_id IS NOT NULL)),
 CHECK (task_id IS NULL OR feature_id IS NOT NULL)
);
