CREATE TABLE attempts (
 "id" TEXT PRIMARY KEY,
 "feature_id" TEXT NOT NULL REFERENCES features(id) DEFERRABLE INITIALLY DEFERRED,
 "task_id" TEXT REFERENCES tasks(id) DEFERRABLE INITIALLY DEFERRED,
 "phase" TEXT NOT NULL,
 "status" TEXT NOT NULL,
 "input_version" INTEGER NOT NULL,
 "documents" JSON NOT NULL CHECK ("documents" IS NULL OR json_valid("documents")),
 "binding" JSON NOT NULL CHECK ("binding" IS NULL OR json_valid("binding")),
 "context_content" TEXT NOT NULL,
 "context_revision" INTEGER NOT NULL,
 "paused" BOOLEAN NOT NULL,
 "revision" INTEGER NOT NULL
, baseline TEXT, outputs JSON NOT NULL DEFAULT '[]' CHECK(json_valid(outputs)), scope JSON CHECK(scope IS NULL OR json_valid(scope)), git_context JSON CHECK(git_context IS NULL OR json_valid(git_context)), live_sessions JSON NOT NULL DEFAULT '{}' CHECK(json_valid(live_sessions)), source_base TEXT);
