INSERT INTO "governance_records" VALUES('builtin-spec-planning-v1','spec','builtin-spec-planning','{"kind":"global"}','需求与方案 Spec',1,NULL,'80e2b450ac4279b7af14877b787bfdb526bcdff7f8cfc4a46950302926c75cd8','{"body":"需求与验收可追踪，明确约束和失败路径。需求交付先独立评审；方案阶段再评审设计、TaskPlan、TestPlan 的一致性与验证方法。缺少未来实现不构成当前规划失败。","rules":["traceability"],"slots":[]}',1,1,1794194466003);
