INSERT INTO "governance_records" VALUES('builtin-spec-merge-v1','spec','builtin-spec-merge','{"kind":"global"}','候选与合入 Spec',1,NULL,'cffb17b355fa02f632ad8828062c8c7423c694494664cc059150bf669e164b12','{"body":"已接受源交付，基于精确目标基线构造单父候选，在同一候选上测试及独立 Review。主干推进前等待人确认；CAS 与远端精确 lease 均需回执，未知结果先核对。","rules":["traceability"],"slots":[]}',1,1,1794194466003);
