 "origin" TEXT NOT NULL, binding JSON NOT NULL DEFAULT '{}' CHECK(json_valid(binding)), binding_verified BOOLEAN NOT NULL DEFAULT 0, result_artifact TEXT REFERENCES artifacts(id) DEFERRABLE INITIALLY DEFERRED,
