CREATE TABLE tasks (
 "id" TEXT PRIMARY KEY,
 "feature_id" TEXT NOT NULL REFERENCES features(id) DEFERRABLE INITIALLY DEFERRED,
 "title" TEXT NOT NULL,
 "status" TEXT NOT NULL,
 "revision" INTEGER NOT NULL,
 "binding" JSON NOT NULL CHECK ("binding" IS NULL OR json_valid("binding")),
 "inherited_snapshot" TEXT NOT NULL REFERENCES snapshots(id) DEFERRABLE INITIALLY DEFERRED,
 "dependencies" JSON NOT NULL CHECK ("dependencies" IS NULL OR json_valid("dependencies")),
 "worktree" TEXT NOT NULL
, scope JSON NOT NULL DEFAULT '{"requirement":null,"design":null,"acceptance":[]}' CHECK(json_valid(scope)));
INSERT INTO "tasks" VALUES('3667d945-1cf1-4778-8359-b831df49e252','5f267ae7-93d5-4ab6-8162-54d62c32ad03','Legacy migration fixture','completed',6,'{"agent":"6f70e187-5a98-4ea2-a02d-d764daa98650","harness":"sim-harness-v1","sandbox":"sim-sandbox-v1","skills":["f2631779-edd3-467e-ae05-734564ada4eb"],"standard":"e7cfa820-4172-4bcb-abe0-8cbb39a7a6c5"}','a190dc9f-f022-4f84-abb7-45e505aca9af','[]','logical-worktree/3667d945-1cf1-4778-8359-b831df49e252','{"acceptance":["AC-1"],"design":"ef220966-438a-4e79-989d-39f3d7b9b264","requirement":"7bef8fe7-57ee-4245-96a5-c0555de0a636"}');
CREATE TABLE turns (
 id TEXT PRIMARY KEY,
 project_id TEXT NOT NULL REFERENCES projects(id) DEFERRABLE INITIALLY DEFERRED,
 session_id TEXT NOT NULL,
 client_message_id TEXT NOT NULL,
 input TEXT NOT NULL,
 input_digest TEXT NOT NULL,
 status TEXT NOT NULL,
 external_message TEXT,
 external_turn TEXT,
 consumed BOOLEAN NOT NULL,
 started INTEGER,
 finished INTEGER,
 run_id TEXT REFERENCES runs(id) DEFERRABLE INITIALLY DEFERRED,
 revision INTEGER NOT NULL, cancel_requested BOOLEAN NOT NULL DEFAULT 0, input_snapshot TEXT REFERENCES snapshots(id) DEFERRABLE INITIALLY DEFERRED, source_revision INTEGER, code_view JSON CHECK(code_view IS NULL OR json_valid(code_view)),
 UNIQUE(project_id,session_id,id),
 UNIQUE(session_id,id),
 UNIQUE(session_id,client_message_id),
 FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX idx_features_project_id ON features("project_id");
CREATE INDEX idx_features_status ON features("status");
CREATE INDEX idx_tasks_feature_id ON tasks("feature_id");
CREATE INDEX idx_tasks_status ON tasks("status");
CREATE INDEX idx_attempts_feature_id ON attempts("feature_id");
CREATE INDEX idx_attempts_task_id ON attempts("task_id");
CREATE INDEX idx_attempts_status ON attempts("status");
CREATE INDEX idx_runs_attempt_id ON runs("attempt_id");
CREATE INDEX idx_runs_merge_id ON runs("merge_id");
CREATE INDEX idx_runs_status ON runs("status");
CREATE INDEX idx_runs_session_id ON runs("session_id");
CREATE INDEX idx_sessions_owner_id ON sessions("owner_id");
CREATE INDEX idx_sessions_snapshot_id ON sessions("snapshot_id");
CREATE INDEX idx_contexts_owner_id ON contexts("owner_id");
CREATE INDEX idx_deliveries_feature_id ON deliveries("feature_id");
CREATE INDEX idx_deliveries_task_id ON deliveries("task_id");
CREATE INDEX idx_deliveries_attempt_id ON deliveries("attempt_id");
CREATE INDEX idx_deliveries_merge_id ON deliveries("merge_id");
CREATE INDEX idx_deliveries_kind ON deliveries("kind");
CREATE INDEX idx_deliveries_artifact_id ON deliveries("artifact_id");
CREATE INDEX idx_reviews_delivery_id ON reviews("delivery_id");
CREATE INDEX idx_reviews_run_id ON reviews("run_id");
CREATE INDEX idx_overrides_delivery_id ON overrides("delivery_id");
CREATE INDEX idx_merges_feature_id ON merges("feature_id");
CREATE INDEX idx_merges_task_id ON merges("task_id");
CREATE INDEX idx_merges_status ON merges("status");
CREATE INDEX idx_heads_project_id ON heads("project_id");
CREATE INDEX idx_resources_run_id ON resources("run_id");
CREATE INDEX idx_resources_kind ON resources("kind");
CREATE INDEX idx_resources_status ON resources("status");
CREATE INDEX idx_events_kind ON events("kind");
CREATE INDEX idx_events_time ON events("time");
CREATE INDEX idx_effects_run ON effects(run_id);
CREATE INDEX idx_effects_status ON effects(status);
CREATE INDEX idx_advances_target ON advances(target);
CREATE UNIQUE INDEX sessions_project_identity ON sessions(project_id,id);
CREATE UNIQUE INDEX sessions_external_identity ON sessions(json_extract(runtime_binding,'$.installation.id'),external_session) WHERE scope IS NOT NULL AND external_session IS NOT NULL;
CREATE UNIQUE INDEX turns_one_active ON turns(session_id) WHERE status NOT IN ('completed','failed','cancelled');
CREATE INDEX turns_project_session ON turns(project_id,session_id);
CREATE INDEX conversation_events_turn ON conversation_events(turn_id,sequence);
CREATE INDEX idx_documents_feature_id ON documents("feature_id");
CREATE INDEX idx_documents_task_id ON documents("task_id");
CREATE INDEX idx_documents_kind ON documents("kind");
CREATE INDEX idx_documents_requirement_id ON documents("requirement_id");
CREATE INDEX idx_documents_design_id ON documents("design_id");
CREATE INDEX idx_documents_project_id ON documents(project_id);
CREATE INDEX idx_snapshots_feature_id ON snapshots("feature_id");
CREATE INDEX idx_snapshots_task_id ON snapshots("task_id");
CREATE INDEX idx_snapshots_kind ON snapshots("kind");
CREATE INDEX idx_snapshots_delivery_id ON snapshots("delivery_id");
CREATE INDEX idx_snapshots_project_id ON snapshots(project_id);
CREATE INDEX idx_artifacts_feature_id ON artifacts("feature_id");
CREATE INDEX idx_artifacts_task_id ON artifacts("task_id");
CREATE INDEX idx_artifacts_project_id ON artifacts(project_id);
CREATE INDEX idx_governance_kind ON governance_records(kind,definition_id,version);
CREATE INDEX idx_governance_scope ON governance_records(json_extract(scope,'$.project_id'),kind);
CREATE UNIQUE INDEX idx_governance_published_version ON governance_records(kind,definition_id,version) WHERE kind IN ('model','tool','harness','agent','workflow','standard','skill','spec','project_configuration');
CREATE UNIQUE INDEX idx_feature_configuration_lock ON governance_records(definition_id) WHERE kind='feature_lock';
CREATE TRIGGER governance_immutable_update BEFORE UPDATE ON governance_records WHEN OLD.immutable=1 BEGIN SELECT RAISE(ABORT,'immutable configuration'); END;
CREATE TRIGGER governance_no_delete BEFORE DELETE ON governance_records BEGIN SELECT RAISE(ABORT,'configuration history cannot be deleted'); END;
CREATE TRIGGER governance_identity_update BEFORE UPDATE ON governance_records WHEN NEW.id!=OLD.id OR NEW.kind!=OLD.kind OR NEW.definition_id!=OLD.definition_id OR NEW.scope!=OLD.scope BEGIN SELECT RAISE(ABORT,'configuration identity cannot change'); END;
CREATE TRIGGER agent_instance_binding_update BEFORE UPDATE ON governance_records WHEN OLD.kind='agent_instance' AND (json_extract(NEW.data,'$.agent_revision_id')!=json_extract(OLD.data,'$.agent_revision_id') OR json_extract(NEW.data,'$.scope')!=json_extract(OLD.data,'$.scope')) BEGIN SELECT RAISE(ABORT,'AgentID binding cannot change'); END;
COMMIT;
PRAGMA user_version=34;
